brands=['Summit Arc','Strideforge','Courtwell','Peakline','Fieldcrest Athletics']
def price(name):
    n=name.lower()
    for words,value in [('treadmill',89999),('kayak',34999),('paddle board',29999),('walking pad',24999),('rowing machine',39999),('exercise bike',34999),('iron set',44999),('squat rack',29999),('driver',24999),('rangefinder',15999),('tent',14999),('dumbbell',19999),('barbell',14999),('weight bench',15999),('portable basketball hoop',29999),('bike',11999),('shoes',9999),('boots',11999),('cleats',7499),('sneakers',7999),('jacket',9999),('coat',8999),('puffer',8999),('jersey',5999),('golf club',11999),('fairway',17999),('hybrid',14999),('wedge',8999),('putter',10999),('cooler',7999),('sleeping bag',6999),('massage gun',8999),('bat',9999),('racket',7999),('paddle',6999),('gift',4999),('net',6999),('goal',8999),('backpack',5999),('pack',2499),('bag',4499),('hoodie',5499),('pants',4999),('leggings',4499),('tights',4499),('shorts',2999),('polo',3999),('swimsuit',4499),('bra',3499),('tee',2499),('tank',2499),('cap',2199),('socks',1599),('sock',1599),('ball',2499),('mat',3499),('glove',2499),('tumbler',2999),('bottle',2499),('chair',4999),('lantern',3499),('headlamp',2999),('tent',14999)]:
        if words in n:return value
    return 3499
products=[]
for cat,names in rows.items():
    kinds=names.split('|')
    assert len(kinds)==(50 if cat=='Sports' else 25),(cat,len(kinds))
    for i,kind in enumerate(kinds):
        brand=brands[(len(products)+i)%len(brands)]
        sport='Multisport'
        lower=kind.lower()
        for key,label in [('basketball','Basketball'),('soccer','Soccer'),('baseball','Baseball'),('softball','Softball'),('football','Football'),('golf','Golf'),('tennis','Tennis'),('pickleball','Pickleball'),('volleyball','Volleyball'),('hockey','Hockey'),('lacrosse','Lacrosse'),('badminton','Badminton'),('rugby','Rugby'),('wrestling','Wrestling'),('gymnastics','Gymnastics'),('archery','Archery'),('running','Running'),('yoga','Yoga'),('swim','Swimming'),('ski','Skiing'),('cycling','Cycling'),('hiking','Hiking'),('camp','Camping'),('fishing','Fishing'),('kayak','Paddling')]:
            if key in lower:sport=label;break
        if cat=='Golf':sport='Golf'
        context={'The Holiday Shop':'A ready-to-give pick for active friends and family.', 'Sports':'Built for skill practice and recreational play.', 'Golf':'An essential for time on the course or the practice range.', 'Shoes':'Athletic footwear for your next session or everyday movement.', 'Women':'An active wardrobe essential for training and everyday wear.', 'Men':'An active wardrobe essential for training and everyday wear.', 'Kids':'Youth-sized gear for active days and outdoor adventures.', 'Accessories':'A useful finishing touch for your active routine.', 'Fan Shop':'Celebrate a fictional team on game day or around town.', 'Exercise & Wellness':'An addition to your home training and recovery routine.', 'Outdoor':'Gear up for weekends on the trail, at camp, or on the water.'}[cat]
        products.append(dict(id=f'SP-{len(products)+1:04d}',name=f'{brand} {kind}',description=f'{kind}. {context}',sport=sport,category=cat,product_type=kind,brand=brand,price_cents=price(kind),currency='USD'))
assert len(products)==300
assert len({p['name'] for p in products})==300
for target in ['commerceos/data/products.json','sites/commerceos/dist/products.json']:
    Path(target).write_text(json.dumps(products,indent=2)+'\n')
Path('sites/commerceos/dist/categories.json').write_text(json.dumps(list(rows),indent=2)+'\n')
print({cat:sum(p['category']==cat for p in products) for cat in rows})
